{"answer":"The company was founded in 1985. Its mission is to make technology accessible to everyone.","program":"# Get relevant documents via search
results = search('company founded mission', limit=10)
# Find founded year and mission statement
founded_year = None
mission = None
for r in results:
    text = r['content']
    if 'founded' in text.lower() and founded_year is None:
        import re
        m = re.search(r'\b(19\d{2}|20\d{2})\b', text)
        if m:
            founded_year = m.group(1)
    if 'mission' in text.lower() and mission is None:
        # simple extraction of the sentence containing "mission"
        sentences = re.split(r'(?<=[.!?])\s+', text)
        for s in sentences:
            if 'mission' in s.lower():
                mission = s.strip()
                break
# Output
print(f"Founded year: {founded_year}")
print(f"Mission: {mission}")"}

