{"code":"import json, re
from pathlib import Path

# Get list of documents
docs = await list_documents()
quarterly_docs = []
for doc in docs:
    title = doc.get('title', '') or ''
    # Check for 'Quarterly Report' in title or Q1-Q4 pattern
    if 'Quarterly Report' in title or re.search(r"\bQ[1-4]\b", title, flags=re.IGNORECASE):
        quarterly_docs.append(doc)

print(f"Found {len(quarterly_docs)} quarterly report documents.")

# Function to parse revenue from text
revenue_pattern = re.compile(r'Revenue\s*[:\-]?\s*\$?([\d,.]+)([MmBb])?', flags=re.IGNORECASE)

total_revenue = 0.0
for doc in quarterly_docs:
    try:
        content_path = Path(f"/documents/{doc['id']}/content.txt")
        text = content_path.read_text()
    except Exception as e:
        print(f"Error reading {doc['title']} ({doc['id']}): {e}")
        continue
    matches = revenue_pattern.findall(text)
    if not matches:
        # Try searching items.jsonl for revenue patterns
        try:
            items_path = Path(f"/documents/{doc['id']}/items.jsonl")
            lines = items_path.read_text().splitlines()
            for line in lines:
                item = json.loads(line)
                if 'Revenue' in item.get('text', ''):
                    matches = revenue_pattern.findall(item['text'])
                    if matches:
                        break
        except Exception as e2:
            print(f"Error reading items.jsonl for {doc['title']} ({doc['id']}): {e2}")
    if not matches:
        print(f"No revenue found in {doc['title']} ({doc['id']})")
        continue
    # Take first match
    num_str, unit = matches[0]
    try:
        num_val = float(num_str.replace(',', ''))
    except ValueError:
        print(f"Could not parse number {num_str} in {doc['title']} ({doc['id']})")
        continue
    if unit.lower() == 'm':
        num_val *= 1_000_000
    elif unit.lower() == 'b':
        num_val *= 1_000_000_000
    total_revenue += num_val
    print(f"{doc['title']} revenue: {num_val}")

print("Total revenue across all quarterly reports:", total_revenue)
"}

