      "sample_questions": ["示例问题1", "示例问题2"]
    }}
  ],
  "resume_alignment": {{
    "resume_used": true,
    "fit_assessment": "岗位匹配度判断",
    "matching_evidence": ["和 JD 高相关的经历或优势"],
    "risk_gaps": ["可能被追问或不占优的点"],
